"""Render the independent clean-checkout signal audit."""
import json
from pathlib import Path


def add_pipe(w):
    d=json.loads((Path(__file__).parent/'results.json').read_text(encoding='utf8'))
    w.page('SWE-ContextBench Lite  /  Запись наблюдений','Какой код завершения сохранять после тестов',
           'Во всех 20 наблюдаемых командах с pytest оболочка вернула 0. При повторе тех же команд на чистых checkout в 18 случаях сам тестовый инструмент сообщил ошибку.')
    w.p('Из журналов 12 запусков решателя взяли все распознанные команды с pytest. Для каждой команды создали два чистых контейнера того же образа. В первом выполнили исходную строку, во втором сохранили итог pytest в отдельный файл и коды всех процессов Bash. Получили 40 независимых окружений для 20 команд из трёх формулировок одного репозитория. Новых обращений к модели не потребовалось.')
    w.tbl(['Что измерялось','Наблюдение'],[
        ['Наружный код команды','0 у всех 20, включая 18 с ошибкой pytest'],
        ['Код процесса pytest','Из 21 запуска 17 вернули 1, один вернул 4 и три вернули 0'],
        ['Текстовый признак ошибки','11 из 18 обнаружены, 7 пропущены, 0 из 2 ложных тревог'],
        ['Влияние фильтров','Пять кодов 141 у grep, ноль у pytest. У grep не встречался код 1'],
        ['Полнота измерения',str(d['verified'])+' из 20 команд, все 21 кода сверены с PIPESTATUS, 0 тайм-аутов'],
    ],[5.5,11.6],True)
    w.p('Одна строка запускала pytest дважды. Первый вызов вернул 1, второй завершился кодом 0 в режиме collect-only. Запись одного последнего статуса потеряла бы падение тестов и могла бы превратить успешный сбор списка в свидетельство выполнения.')
    w.p('Проверяемая запись может хранить команду, версию checkout, нативный код и режим каждого запуска, статусы фильтров и ссылку на его вывод. Этот тест измеряет достоверность входного сигнала для памяти на двух целевых PR Requests. Влияние такой записи на исправления следующего агента ещё предстоит проверить. Сводки и сырые статусы лежат в repair/pipe_check.','Caption')
    w.source('GNU Bash — как определяется статус конвейера','https://www.gnu.org/software/bash/manual/html_node/Pipelines')
    w.source('pytest — смысл кодов завершения','https://docs.pytest.org/en/stable/reference/exit-codes.html')

    result=json.loads((Path(__file__).parent/'writer'/'results.json').read_text(encoding='utf8'))
    w.page('Память агента  /  Фактическая запись','Что запишет агент, если дать ему код самого pytest',
           'С одной командой и её исходным видимым выводом Qwen3.8-27B верно классифицировала 17 из 20 действий. При добавлении нативной телеметрии она исправила три воздержания. Детерминированный декодер дал тот же итог.')
    w.p('Каждое действие оценивается дважды в новом контексте. В одном запросе поля кода и режима pytest имеют значение unknown, в другом они заполнены результатами чистого повтора. Текст команды, обрезанный вывод первоначального решателя, обозначения классов и объяснение кодов одинаковы. Правило для команд с несколькими pytest и порядок 40 запросов зафиксированы заранее.')
    methods=result['methods']
    w.tbl(['Писатель','Верно','Дал ответ¹','Ложно «прошли»','Macro recall²'],
          [[label,str(methods[key]['correct'])+'/20',str(methods[key]['claims'])+'/20',
            str(methods[key]['false_passed']),('{:.1f}%'.format(100*methods[key]['macro_recall_present'])).replace('.',',')]
           for key,label in [('hidden','LLM, без кодов'),('measured','LLM, с кодами'),
                             ('always_fail','Всегда «тесты упали»'),('regex','Regex по выводу'),('decoder','Декодер кодов')]],
          [5.2,2.5,3,3.3,3.1],True)
    w.p('¹ Доля утверждений с определённым исходом, включая ошибки запуска. ² Средняя полнота по трём представленным классам. В выборке 17 команд с падениями тестов, одна с ошибкой использования и две успешные. Отдельных целевых примеров «только сбор тестов» и «неизвестно» нет.','Caption')
    w.p('Во всех трёх изменившихся парах исходный писатель воздержался, а новый записал подтверждённое падение. При независимых командах описательный двусторонний sign test дал бы p=0,25. Здесь 20 действий сгруппированы внутри двух PR Requests. Ошибочных утверждений об успехе не возникло в обеих руках.')
    w.p('На каждую руку ушло 13 742 входных и 40 выходных токенов. Декодеру для этой атомарной записи обращения к модели не понадобились. Проверка влияния такого факта на дальнейшую диагностику и перенос на другие инструменты остаются отдельными экспериментами. Все исходные prompt, ответы, матрицы ошибок и API usage находятся в repair/pipe_check/writer.','Caption')


add_pipe_check=add_pipe

